// Full text: DISCLAIMER.md · Licensed under the MIT License. License: MIT © 2026 dhRobin Systems · Provided as-is, see the disclaimer.
// ============================================================================
// Config & Safety Gate
// Env-only configuration for the dead-lead recycling router.
//   * Safe-ON  flags (SANDBOX_MODE, DRY_RUN, REQUIRE_VERIFIED_EMAIL_FOR_OUTBOUND)
//     turn OFF only on false/0/no/off.
//   * Safe-OFF flags (HUBSPOT_WRITES_ENABLED, SEQUENCE_ENROLLMENT_ENABLED,
//     NURTURE_ROUTING_ENABLED, ENRICHMENT_ENABLED, UPDATE_JOB_TITLE, ...) turn
//     ON only on true/1/yes/on. Typos keep the safe value. Blocked $env => sandbox.
// Tokens never leave this node: only "is set" booleans do.
// ============================================================================
const TRUTHY = ['true', '1', 'yes', 'on'];
const FALSY = ['false', '0', 'no', 'off'];
let envBlocked = false;
function readEnv(key) {
  try {
    const v = $env[key];
    return v === undefined || v === null ? '' : String(v).trim();
  } catch (e) {
    envBlocked = true;
    return '';
  }
}
const str = (k, d = '') => readEnv(k) || d;
const safeOn = (k) => !FALSY.includes(readEnv(k).toLowerCase());
const safeOff = (k) => TRUTHY.includes(readEnv(k).toLowerCase());
const list = (k, d = '') => (readEnv(k).toLowerCase() === 'none' ? '' : readEnv(k) || d).split(',').map((s) => s.trim()).filter(Boolean);
const configErrors = [];
const warnings = [];
const intIn = (k, d, min, max) => {
  const raw = readEnv(k);
  if (raw === '') return d;
  const n = Number(raw);
  if (!/^-?\d+$/.test(raw) || n < min || n > max) { configErrors.push(`${k} must be an integer ${min}-${max} (got "${raw}")`); return d; }
  return n;
};
function jsonEnv(k, fallback) {
  const raw = readEnv(k);
  if (!raw) return fallback;
  if (raw.length > 100000) { configErrors.push(`${k} is larger than 100 KB`); return fallback; }
  try {
    const v = JSON.parse(raw);
    if (!v || typeof v !== 'object' || Array.isArray(v)) { configErrors.push(`${k} must be a JSON object`); return fallback; }
    return v;
  } catch (e) { configErrors.push(`${k} is not valid JSON: ${e.message}`); return fallback; }
}
function regexEnv(k, d) {
  const s = readEnv(k) === '' ? d : readEnv(k);
  if (s === '' || s.toLowerCase() === 'none') return '';
  if (s.length > 400) { configErrors.push(`${k} is longer than 400 characters`); return d; }
  if (/\([^)]*[+*][^)]*\)[+*{]/.test(s) || /\\\d/.test(s)) { configErrors.push(`${k}: nested quantifiers / backreferences are not allowed`); return d; }
  try { new RegExp(s, 'i'); } catch (e) { configErrors.push(`${k}: ${e.message}`); return d; }
  return s;
}
const ID_RE = /^\d{1,18}$/;
const EMAIL_RE = /^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$/i;

// ---- Flags --------------------------------------------------------------------
const sandboxMode = safeOn('SANDBOX_MODE');
const dryRun = safeOn('DRY_RUN');
const writesEnabled = safeOff('HUBSPOT_WRITES_ENABLED');
const sequenceEnabled = safeOff('SEQUENCE_ENROLLMENT_ENABLED');
const nurtureEnabled = safeOff('NURTURE_ROUTING_ENABLED');
const enrichmentEnabled = safeOff('ENRICHMENT_ENABLED');
const hasHubspotToken = readEnv('HUBSPOT_PRIVATE_APP_TOKEN') !== '';
const hasEnrichmentKey = readEnv('ENRICHMENT_API_KEY') !== '';
if (!sandboxMode && !hasHubspotToken) throw new Error('Live mode (SANDBOX_MODE=false) refused: HUBSPOT_PRIVATE_APP_TOKEN is not set. Set it or keep SANDBOX_MODE=true.');

const nowMs = (() => { const o = str('NOW_OVERRIDE'); return o && !Number.isNaN(Date.parse(o)) ? Date.parse(o) : Date.now(); })();
const DAY = 86400000;

// ---- Hosts ------------------------------------------------------------------------
function checkBase(key, def, allowKey, allowDef, withPath) {
  const v = str(key, def).replace(/\/+$/, '');
  if (!v) return null;
  const allowed = list(allowKey, allowDef).map((h) => h.toLowerCase());
  const m = v.match(withPath ? /^(https?):\/\/([a-z0-9.-]+)(?::(\d{1,5}))?(\/[A-Za-z0-9._~\/-]*)?$/i : /^(https?):\/\/([a-z0-9.-]+)(?::(\d{1,5}))?$/i);
  if (!m) { configErrors.push(`${key} must be scheme://host[:port]${withPath ? '[/path]' : ''} with no query string or credentials`); return null; }
  const host = m[2].toLowerCase();
  if (!allowed.some((s) => (s.startsWith('.') ? host.endsWith(s) : host === s))) { configErrors.push(`${key} host ${host} is not in ${allowKey}`); return null; }
  if (m[1].toLowerCase() !== 'https' && !/^(127\.0\.0\.1|localhost)$/.test(host)) { configErrors.push(`${key} must use https`); return null; }
  return v;
}
const hubspotBase = checkBase('HUBSPOT_API_BASE_URL', 'https://api.hubapi.com', 'HUBSPOT_ALLOWED_HOSTS', 'api.hubapi.com,api-eu1.hubapi.com', false);

// ---- Cooling-off and population ----------------------------------------------------
const coolingDays = intIn('COOLING_OFF_DAYS', 120, 1, 3650);
const lookbackDays = intIn('LOOKBACK_DAYS', 730, 1, 3650);
const reevaluateDays = intIn('REEVALUATION_INTERVAL_DAYS', 30, 0, 3650);
const maxRecycles = intIn('MAX_RECYCLES', 2, 1, 50);
const closedLostStages = list('CLOSED_LOST_STAGES', 'closedlost');
const dqStatuses = list('DISQUALIFIED_LEAD_STATUSES', 'UNQUALIFIED,BAD_TIMING');
const dqDateProp = str('DISQUALIFIED_DATE_PROPERTY', 'recycle_disqualified_at');
if (!/^[a-z][a-z0-9_]{0,99}$/.test(dqDateProp)) configErrors.push('DISQUALIFIED_DATE_PROPERTY must be a HubSpot internal property name');
if (!closedLostStages.length && !dqStatuses.length) configErrors.push('Set CLOSED_LOST_STAGES and/or DISQUALIFIED_LEAD_STATUSES');
const cutoffMs = nowMs - coolingDays * DAY;
const lookbackStartMs = cutoffMs - lookbackDays * DAY;

// ---- Qualification rules --------------------------------------------------------------
const rules = {
  excludeLifecycle: list('EXCLUDE_LIFECYCLE_STAGES', 'customer,evangelist').map((s) => s.toLowerCase()),
  excludeLostReasons: regexEnv('EXCLUDE_LOST_REASONS_REGEX', '\\b(do not contact|legal|fraud|spam|bankrupt|out of business)\\b'),
  nurtureOnlyLostReasons: regexEnv('NURTURE_ONLY_LOST_REASONS_REGEX', '\\b(competitor|went with|chose|signed with|multi-year)\\b'),
  outboundTitle: regexEnv('OUTBOUND_TITLE_REGEX', '\\b(chief|c[eotfmr]o|vp|vice president|head of|director|founder|co-founder|owner|president|partner)\\b'),
  targetTitle: regexEnv('TARGET_TITLE_REGEX', '\\b(manager|lead|director|head|vp|chief|c[eotfmr]o|founder|owner|president|partner|specialist|architect|engineer)\\b'),
  excludeTitle: regexEnv('EXCLUDE_TITLE_REGEX', '\\b(student|intern|retired|unemployed|freelance|job seeker)\\b'),
  requireVerifiedForOutbound: safeOn('REQUIRE_VERIFIED_EMAIL_FOR_OUTBOUND'),
  nurtureAllowRisky: safeOff('NURTURE_ALLOW_RISKY'),
  updateJobTitle: safeOff('UPDATE_JOB_TITLE'),
  setLeadStatusOnRoute: str('SET_LEAD_STATUS_ON_ROUTE', ''),
};
if (rules.setLeadStatusOnRoute && !/^[A-Z_]{2,40}$/.test(rules.setLeadStatusOnRoute)) configErrors.push('SET_LEAD_STATUS_ON_ROUTE must be a hs_lead_status internal value such as OPEN');

// ---- Enrichment adapter ---------------------------------------------------------------
const enrichmentMode = str('ENRICHMENT_MODE', 'none').toLowerCase();
if (!['none', 'http'].includes(enrichmentMode)) configErrors.push('ENRICHMENT_MODE must be none or http');
const enrichmentUrl = enrichmentMode === 'http' ? checkBase('ENRICHMENT_API_URL', '', 'ENRICHMENT_ALLOWED_HOSTS', '', true) : null;
if (enrichmentMode === 'http' && !readEnv('ENRICHMENT_API_URL')) configErrors.push('ENRICHMENT_MODE=http requires ENRICHMENT_API_URL');
const authHeader = str('ENRICHMENT_AUTH_HEADER', 'Authorization');
if (!/^[A-Za-z0-9-]{1,64}$/.test(authHeader)) configErrors.push('ENRICHMENT_AUTH_HEADER must be a header name');
const responseMap = { emailStatus: 'email_status', jobTitle: 'job_title', company: 'company', stillAtCompany: 'still_at_company', ...jsonEnv('ENRICHMENT_RESPONSE_MAP_JSON', {}) };
for (const [k, v] of Object.entries(responseMap)) if (typeof v !== 'string' || !/^[A-Za-z0-9_.\[\]-]{1,120}$/.test(v)) configErrors.push(`ENRICHMENT_RESPONSE_MAP_JSON.${k} must be a dotted path`);
const statusMap = { valid: 'VALID', deliverable: 'VALID', ok: 'VALID', invalid: 'INVALID', undeliverable: 'INVALID', bounced: 'INVALID', risky: 'RISKY', catch_all: 'RISKY', 'accept_all': 'RISKY', unknown: 'UNKNOWN', ...jsonEnv('ENRICHMENT_EMAIL_STATUS_MAP_JSON', {}) };
for (const [k, v] of Object.entries(statusMap)) if (!['VALID', 'INVALID', 'RISKY', 'UNKNOWN'].includes(v)) configErrors.push(`ENRICHMENT_EMAIL_STATUS_MAP_JSON.${k} must map to VALID, INVALID, RISKY or UNKNOWN`);
const enrichmentBlockers = [];
if (sandboxMode) enrichmentBlockers.push('SANDBOX_MODE=true (enrichment simulated from the fixture)');
if (enrichmentMode !== 'http') enrichmentBlockers.push('ENRICHMENT_MODE is not http');
if (!enrichmentEnabled) enrichmentBlockers.push('ENRICHMENT_ENABLED is not true');
if (!hasEnrichmentKey) enrichmentBlockers.push('ENRICHMENT_API_KEY is not set');
if (enrichmentMode === 'http' && !enrichmentUrl) enrichmentBlockers.push('ENRICHMENT_API_URL is invalid or not allowlisted');

// ---- Routing targets ---------------------------------------------------------------------
const seqRaw = jsonEnv('SEQUENCE_MAP_JSON', {});
const sequenceMap = {};
for (const [k, v] of Object.entries(seqRaw)) { if (['CLOSED_LOST', 'DISQUALIFIED'].includes(k) && ID_RE.test(String(v))) sequenceMap[k] = String(v); else configErrors.push(`SEQUENCE_MAP_JSON.${String(k).slice(0, 30)} must be CLOSED_LOST or DISQUALIFIED -> numeric sequence id`); }
const senderRaw = jsonEnv('OWNER_SENDER_MAP_JSON', {});
const ownerSenders = {};
for (const [k, v] of Object.entries(senderRaw)) { if (ID_RE.test(k) && v && ID_RE.test(String(v.userId)) && EMAIL_RE.test(String(v.senderEmail || ''))) ownerSenders[k] = { userId: String(v.userId), senderEmail: String(v.senderEmail) }; else configErrors.push(`OWNER_SENDER_MAP_JSON.${String(k).slice(0, 30)} needs {"userId":"…","senderEmail":"…"}`); }
const defaultSender = readEnv('DEFAULT_SENDER_USER_ID') || readEnv('DEFAULT_SENDER_EMAIL') ? { userId: readEnv('DEFAULT_SENDER_USER_ID'), senderEmail: readEnv('DEFAULT_SENDER_EMAIL') } : null;
if (defaultSender && (!ID_RE.test(defaultSender.userId) || !EMAIL_RE.test(defaultSender.senderEmail))) configErrors.push('DEFAULT_SENDER_USER_ID must be numeric and DEFAULT_SENDER_EMAIL a valid address (both required)');
const nurtureListId = readEnv('NURTURE_LIST_ID');
if (nurtureListId && !ID_RE.test(nurtureListId)) configErrors.push('NURTURE_LIST_ID must be a numeric HubSpot list id');

const caps = {
  outboundPerRun: intIn('MAX_OUTBOUND_PER_RUN', 50, 0, 10000),
  outboundPerOwner: intIn('MAX_OUTBOUND_PER_OWNER', 15, 0, 10000),
  nurturePerRun: intIn('MAX_NURTURE_PER_RUN', 500, 0, 100000),
  enrichmentPerRun: intIn('ENRICHMENT_MAX_PER_RUN', 200, 0, 10000),
};
const searchPageSize = intIn('HUBSPOT_SEARCH_PAGE_SIZE', 200, 10, 200);

// ---- Write gates -------------------------------------------------------------------------
const baseBlockers = [];
if (sandboxMode) baseBlockers.push('SANDBOX_MODE=true (synthetic fixture, nothing is written)');
if (dryRun) baseBlockers.push('DRY_RUN=true (routing report only)');
if (envBlocked) baseBlockers.push('n8n blocked $env access');
if (configErrors.length) baseBlockers.push(`${configErrors.length} configuration error(s)`);
const gate = (flag, label, extra = []) => { const b = [...baseBlockers, ...(flag ? [] : [`${label} is not true`]), ...extra]; return { allowed: b.length === 0, blockers: b }; };
const writesGate = gate(writesEnabled, 'HUBSPOT_WRITES_ENABLED');
const sequenceGate = gate(sequenceEnabled && writesEnabled, 'SEQUENCE_ENROLLMENT_ENABLED (+ HUBSPOT_WRITES_ENABLED)', Object.keys(sequenceMap).length ? [] : ['SEQUENCE_MAP_JSON is empty']);
const nurtureGate = gate(nurtureEnabled && writesEnabled, 'NURTURE_ROUTING_ENABLED (+ HUBSPOT_WRITES_ENABLED)');
if (!Object.keys(sequenceMap).length) warnings.push('SEQUENCE_MAP_JSON is empty: outbound-qualified contacts are routed to nurture instead (flag OUTBOUND_UNAVAILABLE).');
if (enrichmentMode === 'none') warnings.push('ENRICHMENT_MODE=none: emails are only screened with HubSpot bounce / opt-out signals and count as UNVERIFIED; with REQUIRE_VERIFIED_EMAIL_FOR_OUTBOUND=true nobody is routed to a sequence.');

const CONTACT_PROPS = ['email', 'firstname', 'lastname', 'jobtitle', 'company', 'hs_lead_status', 'lifecyclestage', 'hubspot_owner_id', 'hs_email_optout', 'hs_email_hard_bounce_reason_enum', 'hs_email_bad_address', 'hs_email_quarantined', 'notes_last_contacted', 'hs_last_sales_activity_timestamp', 'hs_sales_email_last_replied', 'createdate', 'recycle_status', 'recycle_route', 'recycle_reason', 'recycle_count', 'recycle_last_evaluated_at', 'recycle_last_routed_at', 'recycle_eligible_on', 'recycle_email_status', dqDateProp];
const DEAL_PROPS = ['dealstage', 'pipeline', 'closedate', 'closed_lost_reason', 'hs_is_closed', 'hubspot_owner_id'];
const config = {
  runId: 'rcy-' + new Date(nowMs).toISOString().replace(/[-:.TZ]/g, '').slice(0, 14) + '-' + Math.random().toString(36).slice(2, 8),
  now: new Date(nowMs).toISOString(),
  nowMs,
  envBlocked,
  sandboxMode,
  dryRun,
  cooling: { days: coolingDays, cutoffMs, cutoffIso: new Date(cutoffMs).toISOString(), lookbackDays, lookbackStartIso: new Date(lookbackStartMs).toISOString(), reevaluateDays, maxRecycles },
  population: { closedLostStages, dqStatuses, dqDateProp },
  rules,
  enrichment: { mode: enrichmentMode, url: enrichmentUrl, authHeader, authPrefix: readEnv('ENRICHMENT_AUTH_PREFIX').toLowerCase() === 'none' ? '' : (readEnv('ENRICHMENT_AUTH_PREFIX') || 'Bearer') + ' ', responseMap, statusMap, sendName: safeOn('ENRICHMENT_SEND_NAME'), allowed: enrichmentBlockers.length === 0 && configErrors.length === 0, blockers: enrichmentBlockers, keySet: hasEnrichmentKey, timeoutMs: intIn('ENRICHMENT_TIMEOUT_MS', 15000, 1000, 120000) },
  routing: { sequenceMap, ownerSenders, defaultSender, nurtureListId: nurtureListId || null },
  caps,
  hubspot: {
    base: hubspotBase,
    tokenSet: hasHubspotToken,
    pageSize: searchPageSize,
    contactProps: CONTACT_PROPS,
    dealProps: DEAL_PROPS,
    searches: {
      deals: { url: `${hubspotBase}/crm/v3/objects/deals/search`, body: { filterGroups: [{ filters: [{ propertyName: 'dealstage', operator: 'IN', values: closedLostStages.length ? closedLostStages : ['__none__'] }, { propertyName: 'closedate', operator: 'LTE', value: String(cutoffMs) }, { propertyName: 'closedate', operator: 'GTE', value: String(lookbackStartMs) }] }], properties: DEAL_PROPS, sorts: [{ propertyName: 'closedate', direction: 'ASCENDING' }], limit: searchPageSize } },
      contacts: { url: `${hubspotBase}/crm/v3/objects/contacts/search`, body: { filterGroups: [{ filters: [{ propertyName: 'hs_lead_status', operator: 'IN', values: dqStatuses.length ? dqStatuses : ['__none__'] }] }], properties: ['hs_lead_status'], sorts: [{ propertyName: 'hs_object_id', direction: 'ASCENDING' }], limit: searchPageSize } },
    },
    maxSearchResults: 10000,
  },
  writes: { hubspot: writesGate, sequence: sequenceGate, nurture: nurtureGate },
  configErrors,
  warnings,
};
const safetyDecisions = [
  `Mode: ${sandboxMode ? 'SANDBOX (synthetic fixture, zero network calls)' : dryRun ? 'LIVE DRY-RUN (read-only HubSpot discovery; enrichment only if ENRICHMENT_ENABLED)' : 'LIVE'}`,
  `Cooling-off: ${coolingDays} days (last touch before ${config.cooling.cutoffIso}); closed-lost lookback ${lookbackDays} days; re-evaluate every ${reevaluateDays} days; max ${maxRecycles} recycles`,
  `Enrichment: ${config.enrichment.allowed ? 'ARMED (' + enrichmentMode + ')' : 'OFF (' + enrichmentBlockers.join('; ') + ')'}`,
  `Contact stamps: ${writesGate.allowed ? 'ARMED' : 'BLOCKED'} · Sequence enrollment: ${sequenceGate.allowed ? 'ARMED' : 'BLOCKED'} · Nurture routing: ${nurtureGate.allowed ? 'ARMED' : 'BLOCKED'}`,
  `Caps: ${caps.outboundPerRun} outbound / run, ${caps.outboundPerOwner} per owner, ${caps.nurturePerRun} nurture / run, ${caps.enrichmentPerRun} enrichments / run`,
];
return [{ json: { config, safetyDecisions } }];

// Full text: DISCLAIMER.md · Licensed under the MIT License. License: MIT © 2026 dhRobin Systems · Provided as-is, see the disclaimer.
