const DAY = 86400000;
const resolve = (v) => {
  if (typeof v !== 'string') return v;
  const m = v.match(/^@daysAgo:(-?\d+)(:date)?$/);
  if (!m) return v;
  const iso = new Date(config.nowMs - Number(m[1]) * DAY).toISOString();
  return m[2] ? iso.slice(0, 10) : iso;
};
const props = (o) => Object.fromEntries(Object.entries(o).map(([k, v]) => [k, resolve(v)]));
const allDeals = Object.fromEntries(FIXTURE.deals.map((d) => [String(d.id), props(d.properties)]));
const lookbackStart = Date.parse(config.cooling.lookbackStartIso);
const searchDeals = Object.fromEntries(Object.entries(allDeals).filter(([, p]) => config.population.closedLostStages.includes(p.dealstage) && Date.parse(p.closedate) <= config.cooling.cutoffMs && Date.parse(p.closedate) >= lookbackStart));
const contacts = Object.fromEntries(FIXTURE.contacts.map((c) => [String(c.id), props(c.properties)]));
const dqIds = Object.entries(contacts).filter(([, p]) => config.population.dqStatuses.includes(p.hs_lead_status)).map(([id]) => id);
const dealContacts = Object.fromEntries(Object.keys(searchDeals).map((d) => [d, FIXTURE.associations.dealContacts[d] || []]));
const candidateIds = new Set(dqIds);
for (const l of Object.values(dealContacts)) for (const c of l) candidateIds.add(c);
const contactDeals = {};
const deals = { ...searchDeals };
for (const c of candidateIds) { contactDeals[c] = FIXTURE.associations.contactDeals[c] || []; for (const d of contactDeals[c]) deals[d] = allDeals[d]; }
return [{ json: {
  source: 'synthetic-fixture',
  closedLostDealIds: Object.keys(searchDeals),
  deals,
  dealContacts,
  dqIds,
  contacts: Object.fromEntries([...candidateIds].map((c) => [c, contacts[c]])),
  contactDeals,
  sandbox: { enrichment: FIXTURE.enrichment, activeEnrollments: FIXTURE.activeEnrollments, routing: FIXTURE.sandboxRouting },
} }];

