// ============================================================================
// Collect Closed-Lost Deals & Build Association Reads
// Validates every search page and fails closed when HubSpot reports 10,000+
// matches (the search API cannot page further) or pagination was truncated.
// Emits one v4 batch-read item per 100 deals (deal -> contacts), or a noop.
// ============================================================================
const { config } = $('Config & Safety Gate').first().json;
const pages = $input.all().map((i) => i.json);
const deals = {};
let total = 0;
for (const [i, p] of pages.entries()) {
  if (!p || !Array.isArray(p.results)) throw new Error(`Closed-lost deal search page ${i + 1} is malformed; nothing evaluated.`);
  total = Math.max(total, Number(p.total) || 0);
  for (const d of p.results) deals[String(d.id)] = d.properties || {};
}
if (total >= config.hubspot.maxSearchResults) throw new Error(`HubSpot reports ${total} closed-lost deals in the window (search API limit 10,000). Narrow LOOKBACK_DAYS; nothing evaluated.`);
const last = pages[pages.length - 1] || {};
if (last.paging && last.paging.next && last.paging.next.after) throw new Error('Closed-lost deal search pagination stopped early; nothing evaluated.');
if (Object.keys(deals).length < total) throw new Error(`Closed-lost deal search returned ${Object.keys(deals).length} of ${total} deals; nothing evaluated.`);
const ids = Object.keys(deals).sort();
const items = [];
for (let i = 0; i < ids.length; i += 100) items.push({ json: { url: `${config.hubspot.base}/crm/v4/associations/deals/contacts/batch/read`, body: { inputs: ids.slice(i, i + 100).map((id) => ({ id })) }, deals } });
return items.length ? items : [{ json: { noop: true, deals } }];

