// ============================================================================
// Collect Deal Contacts
// Maps every closed-lost deal to its associated contacts (v4 batch read).
// ============================================================================
const first = $('Collect Deals & Build Association Reads').first().json;
const deals = first.deals;
const dealContacts = {};
const items = $input.all().map((i) => i.json);
if (!(items.length === 1 && items[0].noop)) {
  for (const r of items) {
    if (!r || !Array.isArray(r.results)) throw new Error('Deal -> contact association read returned an unexpected response; nothing evaluated.');
    for (const row of r.results) dealContacts[String(row.from.id)] = (row.to || []).map((t) => String(t.toObjectId));
  }
}
return [{ json: { deals, dealContacts } }];

