// ============================================================================
// Collect Candidates & Build Contact Reads
// Union of (a) contacts on closed-lost deals and (b) contacts whose lead
// status is disqualified. Emits batch reads for contact properties and for
// contact -> deal associations (open-deal check), 100 ids each, or a noop.
// ============================================================================
const { config } = $('Config & Safety Gate').first().json;
const prev = $('Collect Deal Contacts').first().json;
const pages = $input.all().map((i) => i.json);
const dq = new Set();
let total = 0;
for (const [i, p] of pages.entries()) {
  if (!p || !Array.isArray(p.results)) throw new Error(`Disqualified-contact search page ${i + 1} is malformed; nothing evaluated.`);
  total = Math.max(total, Number(p.total) || 0);
  for (const c of p.results) dq.add(String(c.id));
}
if (total >= config.hubspot.maxSearchResults) throw new Error(`HubSpot reports ${total} disqualified contacts (search API limit 10,000). Narrow DISQUALIFIED_LEAD_STATUSES; nothing evaluated.`);
if (dq.size < total) throw new Error(`Disqualified-contact search returned ${dq.size} of ${total}; nothing evaluated.`);
const ids = new Set([...dq]);
for (const list of Object.values(prev.dealContacts)) for (const c of list) ids.add(c);
const all = [...ids].sort();
const H = config.hubspot;
const items = [];
for (let i = 0; i < all.length; i += 100) {
  const chunk = all.slice(i, i + 100);
  items.push({ json: { kind: 'contacts', url: `${H.base}/crm/v3/objects/contacts/batch/read`, body: { properties: H.contactProps, inputs: chunk.map((id) => ({ id })) } } });
  items.push({ json: { kind: 'contactDeals', url: `${H.base}/crm/v4/associations/contacts/deals/batch/read`, body: { inputs: chunk.map((id) => ({ id })) } } });
}
return items.length ? items.map((i) => ({ json: { ...i.json, dqIds: [...dq] } })) : [{ json: { noop: true, dqIds: [] } }];

