// ============================================================================
// Collect Contacts & Build Deal Reads
// Stores contact properties and contact -> deal links, then emits batch reads
// for associated deals that were not in the closed-lost search (open-deal
// check needs hs_is_closed for every associated deal), or a noop.
// ============================================================================
const { config } = $('Config & Safety Gate').first().json;
const reqs = $('Collect Candidates & Build Contact Reads').all().map((i) => i.json);
const res = $input.all().map((i) => i.json);
const known = $('Collect Deal Contacts').first().json.deals;
if (reqs.length !== res.length) throw new Error(`Expected ${reqs.length} batch-read responses, got ${res.length}; nothing evaluated.`);
const contacts = {};
const contactDeals = {};
reqs.forEach((q, i) => {
  const r = res[i];
  if (!r || !Array.isArray(r.results)) throw new Error(`Batch read (${q.kind}) returned an unexpected response; nothing evaluated.`);
  if (q.kind === 'contacts') for (const c of r.results) contacts[String(c.id)] = c.properties || {};
  else for (const row of r.results) contactDeals[String(row.from.id)] = (row.to || []).map((t) => String(t.toObjectId));
});
const need = new Set();
for (const list of Object.values(contactDeals)) for (const d of list) if (!known[d]) need.add(d);
const ids = [...need].sort();
const items = [];
for (let i = 0; i < ids.length; i += 100) items.push({ json: { url: `${config.hubspot.base}/crm/v3/objects/deals/batch/read`, body: { properties: config.hubspot.dealProps, inputs: ids.slice(i, i + 100).map((id) => ({ id })) } } });
return items.length ? items.map((i) => ({ json: { ...i.json, contacts, contactDeals } })) : [{ json: { noop: true, contacts, contactDeals } }];

