// Assemble Candidates
// One canonical candidate set for both the live discovery chain and the
// sandbox fixture: deals, contacts, deal <-> contact links, disqualified ids.
// ============================================================================
const first = $input.first().json;
if (first.source === 'synthetic-fixture') return [{ json: first }];
const dl = $('Collect Deal Contacts').first().json;
const dqIds = $('Collect Candidates & Build Contact Reads').first().json.dqIds || [];
let contacts = {};
let contactDeals = {};
try { const c = $('Collect Contacts & Build Deal Reads').first().json; contacts = c.contacts; contactDeals = c.contactDeals; } catch (e) { /* no candidates */ }
const deals = { ...dl.deals };
const items = $input.all().map((i) => i.json);
if (!(items.length === 1 && items[0].noop) && !items[0].contacts) {
  for (const r of items) {
    if (!r || !Array.isArray(r.results)) throw new Error('Associated-deal batch read returned an unexpected response; nothing evaluated.');
    for (const d of r.results) deals[String(d.id)] = d.properties || {};
  }
}
return [{ json: { source: 'hubspot', closedLostDealIds: Object.keys(dl.deals), deals, dealContacts: dl.dealContacts, dqIds, contacts, contactDeals, sandbox: null } }];

// Full text: DISCLAIMER.md · Licensed under the MIT License. License: MIT © 2026 dhRobin Systems · Provided as-is, see the disclaimer.
// ============================================================================
// Evaluate Cooling-Off & Suppression
// Cooling-off clock = the LATEST of: closed-lost close date, disqualified
// date, last contacted, last sales activity, last sales-email reply and last
// recycle. Any newer touch restarts the clock. A contact is eligible only
// when COOLING_OFF_DAYS have passed since that moment.
// Hard suppressions run first (never re-routed): no email, unsubscribed,
// hard bounce / invalid / quarantined address, DO_NOT_RECYCLE, excluded
// lifecycle stage, open deal, excluded lost reason, recycle cap.
// ============================================================================
const { config } = $('Config & Safety Gate').first().json;
const A = $input.first().json;
const DAY = 86400000;
const R = config.rules;
const rx = (p) => (p ? new RegExp(p, 'i') : null);
const EXCL_LOST = rx(R.excludeLostReasons);
const ms = (v) => { if (v === null || v === undefined || v === '') return null; const s = String(v); const t = /^\d{12,14}$/.test(s) ? Number(s) : Date.parse(/^\d{4}-\d{2}-\d{2}$/.test(s) ? s + 'T00:00:00Z' : s); return Number.isFinite(t) && t > Date.UTC(1990, 0, 1) && t < config.nowMs + DAY ? t : null; };
const truthy = (v) => v === true || String(v).toLowerCase() === 'true';
const closedLost = new Set(A.closedLostDealIds);
// Only transient holds bypass the re-evaluation interval (no daily credit burn
// on, for example, risky emails that will not change overnight).
const RETRYABLE = ['ENRICHMENT_FAILED', 'ENROLLMENT_FAILED', 'ENROLLMENT_CHECK_FAILED', 'ENRICHMENT_CAP', 'OUTBOUND_RUN_CAP', 'OUTBOUND_OWNER_CAP', 'NURTURE_RUN_CAP'];

const candidates = Object.entries(A.contacts).filter(([, p]) => p).map(([id, p]) => {
  const linked = new Set(A.contactDeals[id] || []);
  for (const [d, list] of Object.entries(A.dealContacts)) if (list.includes(id)) linked.add(d);
  const lostDeals = [...linked].filter((d) => closedLost.has(d) || (A.deals[d] && config.population.closedLostStages.includes(A.deals[d].dealstage)));
  const openDeals = [...linked].filter((d) => A.deals[d] && !truthy(A.deals[d].hs_is_closed) && !config.population.closedLostStages.includes(A.deals[d].dealstage));
  const isDq = config.population.dqStatuses.includes(p.hs_lead_status);
  const sources = [...(lostDeals.length ? ['CLOSED_LOST'] : []), ...(isDq ? ['DISQUALIFIED'] : [])];
  const latestLost = lostDeals.map((d) => ms(A.deals[d].closedate)).filter(Boolean).sort((a, b) => b - a)[0] || null;
  const lostReasons = lostDeals.map((d) => String(A.deals[d].closed_lost_reason || '')).filter(Boolean);
  const touches = {
    closedLost: latestLost,
    disqualified: isDq ? ms(p[config.population.dqDateProp]) : null,
    lastContacted: ms(p.notes_last_contacted),
    lastSalesActivity: ms(p.hs_last_sales_activity_timestamp),
    lastReply: ms(p.hs_sales_email_last_replied),
    lastRecycled: ms(p.recycle_last_routed_at),
  };
  const start = Math.max(...Object.values(touches).filter(Boolean), 0) || null;
  const clockFrom = start ? Object.entries(touches).find(([, v]) => v === start)[0] : null;
  const eligibleOnMs = start ? start + config.cooling.days * DAY : null;
  const c = {
    id, ownerId: p.hubspot_owner_id ? String(p.hubspot_owner_id) : null, sources, lostDeals, openDeals, lostReasons,
    email: p.email ? String(p.email).trim().toLowerCase() : '', firstname: p.firstname || '', lastname: p.lastname || '', company: p.company || '', jobtitle: p.jobtitle || '',
    existing: { status: p.recycle_status || '', route: p.recycle_route || '', reason: p.recycle_reason || '', eligibleOn: p.recycle_eligible_on || '', emailStatus: p.recycle_email_status || '', count: Number(p.recycle_count) || 0, lastEvaluated: ms(p.recycle_last_evaluated_at), leadStatus: p.hs_lead_status || '' },
    clockStart: start ? new Date(start).toISOString() : null, clockFrom,
    daysSinceTouch: start ? Math.floor((config.nowMs - start) / DAY) : null,
    eligibleOn: eligibleOnMs ? new Date(eligibleOnMs).toISOString().slice(0, 10) : null,
    eligibleOnMs,
    stage: null, decision: null, reason: null, flags: [],
  };
  const set = (decision, reason) => { c.decision = decision; c.reason = reason; return c; };
  if (!sources.length) return set('SKIP', 'NOT_IN_POPULATION');
  if (!c.email) return set('SUPPRESS', 'NO_EMAIL');
  if (truthy(p.hs_email_optout)) return set('SUPPRESS', 'UNSUBSCRIBED');
  if (p.hs_email_hard_bounce_reason_enum || truthy(p.hs_email_bad_address) || truthy(p.hs_email_quarantined)) return set('SUPPRESS', 'EMAIL_INVALID_HUBSPOT');
  if (c.existing.status === 'DO_NOT_RECYCLE') return set('SUPPRESS', 'DO_NOT_RECYCLE');
  if (R.excludeLifecycle.includes(String(p.lifecyclestage || '').toLowerCase())) return set('SUPPRESS', 'LIFECYCLE_EXCLUDED');
  if (openDeals.length) return set('SUPPRESS', 'OPEN_DEAL');
  if (EXCL_LOST && lostReasons.some((r) => EXCL_LOST.test(r))) return set('SUPPRESS', 'LOST_REASON_EXCLUDED');
  if (c.existing.count >= config.cooling.maxRecycles) return set('SUPPRESS', 'MAX_RECYCLES_REACHED');
  if (!start) return set('HOLD', 'NO_REFERENCE_DATE');
  if (config.nowMs < eligibleOnMs) return set('COOLING', 'COOLING_OFF');
  const recently = c.existing.lastEvaluated && config.nowMs - c.existing.lastEvaluated < config.cooling.reevaluateDays * DAY;
  if (recently && !(['HOLD', 'DEFERRED'].includes(c.existing.status) && RETRYABLE.includes(c.existing.reason))) return set('SKIP', 'RECENTLY_EVALUATED');
  return set('VERIFY', 'COOLED_OFF');
});

// Enrichment budget: longest-cooled first
const toVerify = candidates.filter((c) => c.decision === 'VERIFY').sort((a, b) => a.eligibleOnMs - b.eligibleOnMs || (a.id < b.id ? -1 : 1));
toVerify.slice(config.caps.enrichmentPerRun).forEach((c) => { c.decision = 'DEFERRED'; c.reason = 'ENRICHMENT_CAP'; });
return [{ json: { source: A.source, candidates, sandbox: A.sandbox, populationCounts: { closedLostDeals: A.closedLostDealIds.length, disqualifiedContacts: A.dqIds.length, candidates: candidates.length } } }];

// Full text: DISCLAIMER.md · Licensed under the MIT License. License: MIT © 2026 dhRobin Systems · Provided as-is, see the disclaimer.
// ============================================================================
// Build Enrichment Requests
// One re-verification request per cooled-off contact (email validity + current
// job title / employer) through a provider-agnostic HTTP adapter:
//   POST ENRICHMENT_API_URL  { email, firstName, lastName, company, jobTitle }
// The API key is added by the HTTP node from $env. In SANDBOX_MODE responses
// come from the fixture. When enrichment is off, no request is built and the
// router relies on HubSpot bounce / opt-out signals only (UNVERIFIED).
// ============================================================================
const { config } = $('Config & Safety Gate').first().json;
const b = $input.first().json;
const E = config.enrichment;
const mode = config.sandboxMode ? 'simulate' : E.allowed ? 'live' : null;
const items = [];
if (mode) {
  for (const c of b.candidates.filter((x) => x.decision === 'VERIFY')) {
    const body = { email: c.email, company: c.company || null, jobTitle: c.jobtitle || null };
    if (E.sendName) { body.firstName = c.firstname || null; body.lastName = c.lastname || null; }
    items.push({ json: { mode, contactId: c.id, url: mode === 'live' ? E.url : null, body } });
  }
}
return items.length ? items : [{ json: { noop: true, reason: mode ? 'nothing to verify' : 'enrichment off: ' + E.blockers.join('; ') } }];

// Full text: DISCLAIMER.md · Licensed under the MIT License. License: MIT © 2026 dhRobin Systems · Provided as-is, see the disclaimer.
// ============================================================================
// Simulated Enrichment  (SANDBOX_MODE only; zero network calls)
// Answers from the fixture's synthetic enrichment responses (keyed by email).
// ============================================================================
const fx = $('Load Synthetic Recycle Fixture').first().json.sandbox.enrichment || {};
return $input.all().map((i) => {
  const r = fx[i.json.body.email];
  if (!r) return { json: { email_status: 'unknown' } };
  if (r.__error) return { json: { error: { message: r.__error } } };
  return { json: r };
});

// Full text: DISCLAIMER.md · Licensed under the MIT License. License: MIT © 2026 dhRobin Systems · Provided as-is, see the disclaimer.
// ============================================================================
// Route Re-Entry
// Applies re-verification results, then routes each cooled-off contact:
//   OUTBOUND  verified email + senior title (OUTBOUND_TITLE_REGEX) + lost reason
//             not nurture-only + a sequence for the source + a sender
//   NURTURE   target persona (TARGET_TITLE_REGEX) with a valid / HubSpot-clean
//             email (risky only if NURTURE_ALLOW_RISKY=true)
//   SUPPRESS  invalid email, left the company, excluded or off-persona title
//   HOLD      enrichment failed or email risky -> retried on the next run
// Per-run and per-owner caps defer the overflow (longest-cooled first).
// Builds the contact-property stamps (only when something changed) and the
// routing report.
// ============================================================================
const { config } = $('Config & Safety Gate').first().json;
const ev = $('Evaluate Cooling-Off & Suppression').first().json;
const R = config.rules;
const rx = (p) => (p ? new RegExp(p, 'i') : null);
const OUT_T = rx(R.outboundTitle), TGT_T = rx(R.targetTitle), EXC_T = rx(R.excludeTitle), NURT_LOST = rx(R.nurtureOnlyLostReasons);
// In SANDBOX_MODE only, the fixture's example sequences / senders / list stand in
// for SEQUENCE_MAP_JSON / OWNER_SENDER_MAP_JSON / DEFAULT_SENDER_* when unset.
const SR = config.sandboxMode && ev.sandbox ? ev.sandbox.routing : null;
const ROUTING = {
  sequenceMap: Object.keys(config.routing.sequenceMap).length || !SR ? config.routing.sequenceMap : SR.sequenceMap,
  ownerSenders: Object.keys(config.routing.ownerSenders).length || !SR ? config.routing.ownerSenders : SR.ownerSenders,
  defaultSender: config.routing.defaultSender || (SR ? SR.defaultSender : null),
};
const getPath = (o, p) => p.replace(/\[(\d+)\]/g, '.$1').split('.').reduce((a, k) => (a === null || a === undefined ? undefined : a[k]), o);

// ---- merge enrichment results ------------------------------------------------------
const enrichment = {};
let reqs = [];
try { reqs = $('Build Enrichment Requests').all().map((i) => i.json).filter((q) => !q.noop); } catch (e) { reqs = []; }
const res = $input.all().map((i) => i.json);
const enrichedThisRun = reqs.length > 0 && !(res.length === 1 && res[0].noop);
if (enrichedThisRun) {
  if (res.length !== reqs.length) throw new Error(`Enrichment returned ${res.length} responses for ${reqs.length} requests; nothing routed.`);
  reqs.forEach((q, i) => {
    const r = res[i] || {};
    if (r.error) { enrichment[q.contactId] = { failed: true, message: String(r.error.message || r.error).slice(0, 160) }; return; }
    const M = config.enrichment.responseMap;
    const rawStatus = getPath(r, M.emailStatus);
    const status = rawStatus === undefined || rawStatus === null ? 'UNKNOWN' : config.enrichment.statusMap[String(rawStatus).toLowerCase()] || 'UNKNOWN';
    const sac = getPath(r, M.stillAtCompany);
    enrichment[q.contactId] = { failed: false, emailStatus: status, jobTitle: getPath(r, M.jobTitle) ? String(getPath(r, M.jobTitle)).trim().slice(0, 200) : null, company: getPath(r, M.company) ? String(getPath(r, M.company)).trim().slice(0, 200) : null, stillAtCompany: sac === true || String(sac).toLowerCase() === 'true' ? true : sac === false || String(sac).toLowerCase() === 'false' ? false : null };
  });
}

// ---- route ---------------------------------------------------------------------------
const senderFor = (ownerId) => (ownerId && ROUTING.ownerSenders[ownerId]) || ROUTING.defaultSender;
const decisions = ev.candidates.map((c0) => {
  const c = JSON.parse(JSON.stringify(c0));
  c.emailStatus = c.existing.emailStatus && c.decision !== 'VERIFY' ? c.existing.emailStatus : null;
  if (c.decision !== 'VERIFY') return c;
  c.evaluatedNow = true;
  const e = enrichment[c.id];
  if (!e) { c.emailStatus = 'UNVERIFIED'; c.flags.push(config.enrichment.mode === 'http' ? 'ENRICHMENT_SKIPPED' : 'HUBSPOT_SIGNALS_ONLY'); }
  else if (e.failed) { c.decision = 'HOLD'; c.reason = 'ENRICHMENT_FAILED'; c.flags.push('ENRICHMENT_ERROR'); c.enrichmentError = e.message; c.verified = true; return c; }
  else {
    c.verified = true;
    c.emailStatus = e.emailStatus;
    if (e.jobTitle && e.jobTitle.toLowerCase() !== String(c.jobtitle).toLowerCase()) { c.flags.push('JOB_TITLE_CHANGED'); c.newJobTitle = e.jobTitle; }
    if (e.company && c.company && e.company.toLowerCase() !== c.company.toLowerCase()) c.flags.push('COMPANY_CHANGED');
    if (e.stillAtCompany === false) { c.decision = 'SUPPRESS'; c.reason = 'LEFT_COMPANY'; c.flags.push('JOB_CHANGER'); return c; }
  }
  if (c.emailStatus === 'INVALID') { c.decision = 'SUPPRESS'; c.reason = 'EMAIL_INVALID_VERIFIED'; return c; }
  const title = c.newJobTitle || c.jobtitle || '';
  if (EXC_T && EXC_T.test(title)) { c.decision = 'SUPPRESS'; c.reason = 'TITLE_EXCLUDED'; return c; }
  const outboundEmailOk = c.emailStatus === 'VALID' || (!R.requireVerifiedForOutbound && c.emailStatus === 'UNVERIFIED');
  const nurtureEmailOk = ['VALID', 'UNVERIFIED'].includes(c.emailStatus) || (R.nurtureAllowRisky && ['RISKY', 'UNKNOWN'].includes(c.emailStatus));
  const seqKey = c.sources.includes('CLOSED_LOST') ? 'CLOSED_LOST' : 'DISQUALIFIED';
  const seniorTitle = OUT_T ? OUT_T.test(title) : false;
  const persona = !TGT_T || TGT_T.test(title) || seniorTitle;
  const nurtureOnly = NURT_LOST && c.lostReasons.some((r) => NURT_LOST.test(r));
  if (seniorTitle && outboundEmailOk && !nurtureOnly) {
    const seq = ROUTING.sequenceMap[seqKey];
    const sender = senderFor(c.ownerId);
    if (seq && sender) { c.decision = 'OUTBOUND'; c.reason = `SEQUENCE_${seqKey}`; c.sequenceId = seq; c.sender = sender; return c; }
    c.flags.push(seq ? 'NO_SENDER_FOR_OWNER' : 'OUTBOUND_UNAVAILABLE');
  } else if (seniorTitle && nurtureOnly) c.flags.push('NURTURE_ONLY_LOST_REASON');
  else if (seniorTitle && !outboundEmailOk) c.flags.push('EMAIL_NOT_VERIFIED_FOR_OUTBOUND');
  if (!persona) { c.decision = 'SUPPRESS'; c.reason = 'OFF_PERSONA'; return c; }
  if (!nurtureEmailOk) { c.decision = 'HOLD'; c.reason = 'EMAIL_RISKY'; return c; }
  c.decision = 'NURTURE'; c.reason = `NURTURE_${seqKey}`;
  return c;
});

// ---- caps (longest-cooled first) ---------------------------------------------------------
const byAge = (a, b) => (a.eligibleOnMs || 0) - (b.eligibleOnMs || 0) || (a.id < b.id ? -1 : 1);
const perOwner = {};
let outbound = 0;
for (const c of decisions.filter((d) => d.decision === 'OUTBOUND').sort(byAge)) {
  const k = c.ownerId || 'unowned';
  if (outbound >= config.caps.outboundPerRun || (perOwner[k] || 0) >= config.caps.outboundPerOwner) { c.decision = 'DEFERRED'; c.reason = outbound >= config.caps.outboundPerRun ? 'OUTBOUND_RUN_CAP' : 'OUTBOUND_OWNER_CAP'; continue; }
  outbound++; perOwner[k] = (perOwner[k] || 0) + 1;
}
let nurture = 0;
for (const c of decisions.filter((d) => d.decision === 'NURTURE').sort(byAge)) {
  if (nurture >= config.caps.nurturePerRun) { c.decision = 'DEFERRED'; c.reason = 'NURTURE_RUN_CAP'; continue; }
  nurture++;
}

// ---- report ----------------------------------------------------------------------------------
const count = (k) => decisions.reduce((m, d) => { m[d[k]] = (m[d[k]] || 0) + 1; return m; }, {});
const report = {
  runId: config.runId,
  generatedAt: config.now,
  mode: config.sandboxMode ? 'SANDBOX' : config.dryRun ? 'DRY_RUN' : 'LIVE',
  source: ev.source,
  coolingOffDays: config.cooling.days,
  lastTouchCutoff: config.cooling.cutoffIso,
  population: ev.populationCounts,
  decisions: count('decision'),
  reasons: count('reason'),
  enrichment: { mode: config.sandboxMode ? 'simulated' : config.enrichment.allowed ? config.enrichment.mode : 'off', requested: reqs.length, failed: Object.values(enrichment).filter((e) => e.failed).length },
  outboundByOwner: perOwner,
  outbound: decisions.filter((d) => d.decision === 'OUTBOUND').map((d) => ({ contactId: d.id, ownerId: d.ownerId, sequenceId: d.sequenceId, source: d.reason, emailStatus: d.emailStatus })),
  nurture: decisions.filter((d) => d.decision === 'NURTURE').map((d) => ({ contactId: d.id, source: d.reason, emailStatus: d.emailStatus, flags: d.flags })),
  cooling: decisions.filter((d) => d.decision === 'COOLING').map((d) => ({ contactId: d.id, eligibleOn: d.eligibleOn, clockFrom: d.clockFrom, daysSinceTouch: d.daysSinceTouch })),
  suppressed: decisions.filter((d) => d.decision === 'SUPPRESS').map((d) => ({ contactId: d.id, reason: d.reason })),
  held: decisions.filter((d) => ['HOLD', 'DEFERRED'].includes(d.decision)).map((d) => ({ contactId: d.id, decision: d.decision, reason: d.reason })),
  jobChangers: decisions.filter((d) => d.flags.includes('JOB_CHANGER') || d.flags.includes('JOB_TITLE_CHANGED')).map((d) => ({ contactId: d.id, flags: d.flags })),
  warnings: config.warnings,
  configErrors: config.configErrors,
};
const routed = decisions.filter((d) => ['OUTBOUND', 'NURTURE'].includes(d.decision)).length;
const writeBlockers = [...config.writes.hubspot.blockers];
if (!decisions.some((d) => d.decision !== 'SKIP')) writeBlockers.push('Nothing to evaluate');
return [{ json: { report, decisions, routed, writeAllowed: writeBlockers.length === 0, writeBlockers } }];

// Full text: DISCLAIMER.md · Licensed under the MIT License. License: MIT © 2026 dhRobin Systems · Provided as-is, see the disclaimer.
// ============================================================================
// Dry-Run Routing Report
// Nothing was written, enrolled or added to a list. The report shows every
// contact's decision, cooling-off dates, suppressions and planned routes.
