const P = $input.first().json;
return [{ json: { mode: 'dry-run', writeBlockedBy: P.writeBlockers, report: P.report } }];

// Full text: DISCLAIMER.md · Licensed under the MIT License. License: MIT © 2026 dhRobin Systems · Provided as-is, see the disclaimer.
// ============================================================================
// Build Enrollment Checks
// Before any sequence enrollment, read the contact's current enrollment
// (GET /automation/v4/sequences/enrollments/contact/{id}) so nobody is
// enrolled twice or pulled out of a sequence a rep started manually.
// ============================================================================
const { config } = $('Config & Safety Gate').first().json;
const P = $input.first().json;
const out = P.decisions.filter((d) => d.decision === 'OUTBOUND');
if (!config.writes.sequence.allowed || !out.length) return [{ json: { noop: true } }];
return out.map((d) => ({ json: { contactId: d.id, url: `${config.hubspot.base}/automation/v4/sequences/enrollments/contact/${d.id}` } }));

// Full text: DISCLAIMER.md · Licensed under the MIT License. License: MIT © 2026 dhRobin Systems · Provided as-is, see the disclaimer.
// ============================================================================
// Build Sequence Enrollments
// 404 / no active enrollment -> enroll. An active enrollment -> skip
// (IN_ACTIVE_SEQUENCE). Any other check result -> HOLD (fail closed, retried
// next run). Enrollment body: { contactId, sequenceId, senderEmail } with
// ?userId=<sender user id>; senders come from OWNER_SENDER_MAP_JSON or the
// default sender.
// ============================================================================
const { config } = $('Config & Safety Gate').first().json;
const P = $('Route Re-Entry').first().json;
const checks = {};
let reqs = [];
try { reqs = $('Build Enrollment Checks').all().map((i) => i.json).filter((q) => !q.noop); } catch (e) { reqs = []; }
const res = $input.all().map((i) => i.json);
reqs.forEach((q, i) => {
  const r = res[i] || {};
  const status = Number(r.statusCode);
  const body = r.body && typeof r.body === 'object' ? r.body : {};
  if (r.error && r.statusCode === undefined) checks[q.contactId] = { state: 'CHECK_FAILED', message: String(r.error.message || r.error).slice(0, 160) };
  else if (status === 404) checks[q.contactId] = { state: 'NONE' };
  else if (status >= 200 && status < 300) checks[q.contactId] = body.sequenceId || body.id || body.enrolledAt ? { state: 'ACTIVE', sequenceId: body.sequenceId ? String(body.sequenceId) : null } : { state: 'NONE' };
  else checks[q.contactId] = { state: 'CHECK_FAILED', message: `HTTP ${status}` };
});
const items = [];
for (const d of P.decisions.filter((x) => x.decision === 'OUTBOUND')) {
  const c = checks[d.id];
  if (!c || c.state !== 'NONE') continue;
  items.push({ json: { contactId: d.id, url: `${config.hubspot.base}/automation/v4/sequences/enrollments?userId=${encodeURIComponent(d.sender.userId)}`, body: { contactId: d.id, sequenceId: d.sequenceId, senderEmail: d.sender.senderEmail } } });
}
return items.length ? items.map((i) => ({ json: { ...i.json, checks } })) : [{ json: { noop: true, checks } }];

// Full text: DISCLAIMER.md · Licensed under the MIT License. License: MIT © 2026 dhRobin Systems · Provided as-is, see the disclaimer.
// ============================================================================
// Build Contact Updates
// Final status per contact and the recycle_* property stamps:
//   RECYCLED_OUTBOUND / RECYCLED_NURTURE (routed: recycle_count + 1,
//   recycle_last_routed_at, recycle_route), ELIGIBLE_* (routing gate off),
//   IN_ACTIVE_SEQUENCE, COOLING (+ recycle_eligible_on), SUPPRESSED, HOLD,
//   DEFERRED. A contact is only written when something changed, so daily
//   runs do not churn records. Nurture-routed contacts are also added to
//   NURTURE_LIST_ID (a static list) when configured.
// ============================================================================
const { config } = $('Config & Safety Gate').first().json;
const P = $('Route Re-Entry').first().json;
const EB = $('Build Sequence Enrollments').first().json;
const checks = EB.checks || {};
let enrollReqs = [];
try { enrollReqs = $('Build Sequence Enrollments').all().map((i) => i.json).filter((q) => !q.noop); } catch (e) { enrollReqs = []; }
let enrollRes = [];
try { enrollRes = $('HubSpot: Enroll in Sequence').all().map((i) => i.json); } catch (e) { enrollRes = []; }
const enrolled = {};
enrollReqs.forEach((q, i) => {
  const r = enrollRes[i] || {};
  const s = Number(r.statusCode);
  enrolled[q.contactId] = s >= 200 && s < 300 ? { ok: true } : { ok: false, message: r.error ? String(r.error.message || r.error).slice(0, 160) : `HTTP ${s}: ${JSON.stringify(r.body || {}).slice(0, 120)}` };
});
const seqOn = config.writes.sequence.allowed;
const nurOn = config.writes.nurture.allowed;
const now = config.now;
const outcomes = [];
const updates = [];
const listAdds = [];
for (const d of P.decisions) {
  if (d.decision === 'SKIP') continue;
